import { View, Text, FlatList, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "1", name: "Чихэвч" },
  { id: "2", name: "Гар цаг" },
  { id: "3", name: "Нарны шил" },
  { id: "4", name: "Цүнх" },
];

function App() {
  const [selected, setSelected] = useState("");

  return (
    <View style={styles.screen}>
      <Text nativeID="selected" style={styles.sel}>
        {selected ? "Сонгосон: " + selected : "Бараа сонгоно уу"}
      </Text>
      <FlatList
        data={PRODUCTS}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          // энд бичнэ үү: дарж болох мөр
          <Text style={styles.row}>{item.name}</Text>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8" },
  sel: { fontSize: 18, fontWeight: "bold", padding: 16 },
  row: { backgroundColor: "#ffffff", padding: 16, margin: 8, borderRadius: 12, fontSize: 16 },
});

registerRootComponent(App);

import { View, Text, FlatList, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "1", name: "Чихэвч" },
  { id: "2", name: "Гар цаг" },
  { id: "3", name: "Нарны шил" },
  { id: "4", name: "Цүнх" },
];

function App() {
  const [selected, setSelected] = useState("");

  return (
    <View style={styles.screen}>
      <Text nativeID="selected" style={styles.sel}>
        {selected ? "Сонгосон: " + selected : "Бараа сонгоно уу"}
      </Text>
      <FlatList
        data={PRODUCTS}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <Pressable testID="row" style={styles.row} onPress={() => setSelected(item.name)}>
            <Text style={styles.rowText}>{item.name}</Text>
          </Pressable>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8" },
  sel: { fontSize: 18, fontWeight: "bold", padding: 16 },
  row: { backgroundColor: "#ffffff", padding: 16, margin: 8, borderRadius: 12 },
  rowText: { fontSize: 16 },
});

registerRootComponent(App);
